mapper.select:
select su.user_id as userId, su.user_name as userName, su.dept_id as deptId, su.nick_name as nickName
from sys_user_role as sur
inner join sys_user su on sur.user_id = su.user_id

where sur.role_id in

	#{roleId}


	and su.dept_id in

		#{orgId}



	and su.tenant_id = #{tenantId}

select dept_id as deptId, dept_name as deptName
from sys_dept where dept_id in

	#{deptId}

SELECT ui.user_id,ui.USER_NAME userAccount,ui.user_name,ui.DEPT_ID AS orgId,'' age,ui.sex,ui.email,ui.PHONENUMBER mobilePhone,
CONCAT(SUBSTRING(ui.PHONENUMBER,1,3),'****',SUBSTRING(ui.PHONENUMBER,8)) AS encryption_mobile_phone,ui.TELEPHONE phone,ui.source,
ui.tenant_id,'1' manipulate_level,ui.remark,ui.CREATE_BY creator,ui.CREATE_TIME creator_date,ui.UPDATE_BY modifier,
ui.UPDATE_TIME modifier_date,ui.DEL_FLAG delete_flag,ui.GRADE user_level,ui.province_id,ui.city_id,'' county_id,
'0' is_first,ui.CREATE_TIME show_create_date,
og.DEPT_NAME org_name ,te.tenant_name,
t1.AREA_NAME province_name,
t2.AREA_NAME city_name,
ui.tower_user_source tower_user_source,
'1' map_model,'' tree_choose
FROM sys_user ui
LEFT JOIN sys_dept og ON ui.DEPT_ID=og.DEPT_ID
LEFT JOIN sys_tenant_info te ON ui.tenant_id=te.tenant_id
LEFT JOIN sys_area t1 ON te.province_id = t1.AREA_CODE
LEFT JOIN sys_area t2 ON te.city_id = t2.AREA_CODE
WHERE 1=1

	AND ui.USER_NAME LIKE "%"#{userAccount}"%"


	AND ui.USER_NAME = #{userAccount}


	AND ui.NICK_NAME LIKE "%"#{userName}"%"


	AND ui.PHONENUMBER = #{mobilePhone}


	AND ui.user_id = #{userId}


	AND ui.tenant_id = #{tenantId}


	AND ui.DEL_FLAG = #{deleteFlag}


	AND ui.source = #{source}


	AND og.DEPT_NAME = #{orgName}


	AND og.DEPT_ID = #{orgId}


	AND te.tenant_name LIKE CONCAT('%',#{tenantName},'%')



	AND ui.tenant_id = #{customerCode}




	AND te.province_id = #{provinceId}


	AND te.city_id = #{cityId}






	AND ui.user_id in (select user_id from sys_user_role where role_id = #{roleId})



	AND ui.tenant_id = #{tenantkeyword}



	AND ui.tenant_id in

		#{labelIdItem}



	AND ui.USER_NAME in

		#{labelIdItem}





	AND ui.DEL_FLAG in

		#{labelIdItem}




	AND ui.CREATE_TIME >= #{startDate}



	AND ui.CREATE_TIME <= #{endDate}


ORDER BY ui.CREATE_TIME DESC

	select
   	tenant_id,industry_code,app_ver_code
	from sys_tenant_trade
	where  tenant_id = #{tenantId}
	AND industry_code in

		#{labelIdItem}


		and app_ver_code = #{appVerCode}

select USER_ID 'userId',USER_NAME 'userName',DEPT_ID 'deptId',NICK_NAME 'nickName',PHONENUMBER 'phonenumber',AVATAR avatar,STATUS status from sys_user u
where u.DEL_FLAG ='0' and u.user_id in

#{userId}

select USER_ID 'userId',USER_NAME 'userName',NICK_NAME 'nickName',PHONENUMBER phonenumber,AVATAR avatar,STATUS status from sys_user u
where u.DEL_FLAG ='0' and u.user_name in

	#{userName}

select PARENT_ID
from sys_dept where dept_id in

	#{deptId}

order by DEPT_LEVEL;

select dept_id
from sys_dept where tenant_id = #{tenantId}
order by DEPT_LEVEL;

select dept_id
from sys_dept where STATUS='0' and DEL_FLAG='0'
${dataScope}
order by DEPT_LEVEL;

select dept_id
from sys_dept where STATUS='0' and DEL_FLAG='0'

	and tenant_id = #{param.tenantId}


	and industry_code = #{param.industryCode}

order by DEPT_LEVEL;

SELECT ID,AREA_CODE,AREA_NAME,AREA_LEVEL,AREA_PARENT_CODE,AREA_PARENT_NAME,`STATUS`,LATITUDE,LONGITUDE
FROM sys_area WHERE AREA_CODE IN

	#{areaCode}


and status = #{status}
and sur.role_id = #{roleId}
and d.tenant_id is null	and d.tenant_tower_dept_id is null
and d.tenant_id = #{tenantId}
and (dept_id = #{deptId} OR INSTR(ANCESTORS, #{deptId})>0)
order by d.parent_id ASC, d.dept_id ASC, d.order_num ASC

select industry_id, industry_code, industry_name, industry_desc, create_time, update_time, status, creator, modifier from sys_industry_conf
where industry_code = #{industryCode}

	and	accept_node =#{localNode}

   and delete_flag = 0 limit 1
